```tsx
import { Provider as JotaiProvider, createStore } from "jotai";
import { createContext, useContext, useEffect, useRef } from "react";

import { QuestionnaireRead } from "@/types/questionnaire/questionnaire";

import {
  initializeResponses,
  questionnaireAtom,
  responsesAtom,
  activeGroupIndexAtom,
} from "./store";
import { RendererMode, RendererSubject } from "./types";

interface RendererContextValue {
  mode: RendererMode;
  subject: RendererSubject;
  questionnaire: QuestionnaireRead;
}

const RendererContext = createContext<RendererContextValue | null>(null);

export function useRenderer(): RendererContextValue {
  const context = useContext(RendererContext);
  if (!context) {
    throw new Error("useRenderer must be used inside QuestionnaireRendererProvider");
  }
  return context;
}

interface ProviderProps {
  questionnaire: QuestionnaireRead;
  mode: RendererMode;
  subject?: RendererSubject;
  children: React.ReactNode;
}

export function QuestionnaireRendererProvider({
  questionnaire,
  mode,
  subject = {},
  children,
}: ProviderProps) {
  const storeRef = useRef<ReturnType<typeof createStore> | null>(null);
  if (!storeRef.current) {
    storeRef.current = createStore();
  }

  // Re-seed whenever the questionnaire identity changes (builder preview
  // passes a fresh draft object on each Edit→Preview switch).
  useEffect(() => {
    storeRef.current!.set(questionnaireAtom, questionnaire);
    storeRef.current!.set(responsesAtom, initializeResponses(questionnaire.questions));
    storeRef.current!.set(activeGroupIndexAtom, 0);
  }, [questionnaire]);

  return (
    <RendererContext.Provider value={{ mode, subject, questionnaire }}>
      <JotaiProvider store={storeRef.current}>{children}</JotaiProvider>
    </RendererContext.Provider>
  );
}
```

